const fs=require('fs');
let total=0,fail=0;
function ok(cond,msg){total++;if(!cond){fail++;console.error('FAIL',msg);}else console.log('PASS',msg)}
const loader=fs.readFileSync('prototype-044.js','utf8');
const route=fs.readFileSync('test.html','utf8');
const guard=fs.readFileSync('prototype-045c-release-integrity.js','utf8');
const controller=fs.readFileSync('prototype-046-conversation-engine.js','utf8');
ok(loader.includes('prototype-045c-release-integrity.js?v=046'),'atomic render guard is loaded in 0.4.6');
ok(loader.includes('prototype-046-conversation-engine.js?v=046'),'0.4.6 single-owner conversation engine is loaded');
ok(loader.lastIndexOf('prototype-046-conversation-engine.js')>loader.lastIndexOf('prototype-045c-release-integrity.js'),'0.4.6 conversation engine loads last');
ok(route.includes('Keneflex Test 0.4.6'),'participant route identifies 0.4.6');
ok(route.includes('participant=046'),'participant route requests 0.4.6');
ok(route.includes("cache:'no-store'"),'participant route disables cache');
ok(guard.includes('addAI=rawAddAI'),'historical addAI suppression wrappers are bypassed');
ok(guard.includes('ensurePromptForControl'),'structured controls cannot render without an AI prompt');
ok(guard.includes('KFXReleaseAudit'),'runtime render-integrity audit remains exposed');
ok(controller.includes("hand:'hand',wrist:'hand',thumb:'hand',finger:'hand'"),'hand/wrist/thumb/finger share one canonical problem family');
ok(controller.includes('function candidates(s)'),'single-owner next-question candidate gate exists');
ok(controller.includes("if(!known(t,c))a.push"),'known facts are excluded before question rendering');
ok(controller.includes('askDetail=function()'),'0.4.6 owns the ordinary conversation entry point');
ok(controller.includes('KFX046Audit'),'0.4.6 runtime story/question audit is exposed');
console.log(`\n${total-fail}/${total} release-contract assertions passed`);process.exit(fail?1:0);
